import{_ as t,o as s,c as n,ah as o}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Gestion documentaire","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/gestion-documentaire/index.md","filePath":"src/guide/gestion-documentaire/index.md"}'),r={name:"guide/gestion-documentaire/index.md"};function i(u,e,a,d,l,c){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="gestion-documentaire" tabindex="-1">Gestion documentaire <a class="header-anchor" href="#gestion-documentaire" aria-label="Permalink to &quot;Gestion documentaire&quot;">​</a></h1><p>Le module <strong>Gestion documentaire</strong> range les documents de l&#39;établissement dans des dossiers : celui de chaque élève, celui de chaque employé, et celui de l&#39;établissement lui-même (procès-verbaux, règlements…). Chaque document est classé sous un <strong>type</strong> du catalogue (acte de naissance, dossier médical, contrat de travail…), qui décide qui peut le consulter et qui peut le valider.</p><p>Le <strong>Gestionnaire documentaire</strong> est le profil dédié à ce module : il dépose, classe et vérifie les documents, et tient le catalogue des types. Il n&#39;a accès à aucune fonction académique (notes, bulletins, paiements). D&#39;autres profils utilisent aussi le module, chacun pour les types qui le concernent : le secrétariat pour les pièces d&#39;inscription, l&#39;infirmerie pour les dossiers médicaux, la caisse pour les factures et reçus. Les pages de l&#39;espace <strong>Documents</strong> ne montrent à chacun que les types qui lui sont ouverts.</p><div class="info custom-block"><p class="custom-block-title">Module sur licence</p><p>L&#39;espace <strong>Documents</strong> n&#39;apparaît que si l&#39;établissement a activé le module Gestion documentaire.</p></div><h2 id="la-page-documents" tabindex="-1">La page Documents <a class="header-anchor" href="#la-page-documents" aria-label="Permalink to &quot;La page Documents&quot;">​</a></h2><p>La page <strong>Documents</strong> réunit deux choses :</p><ul><li><strong>Ouvrir un dossier</strong> : tapez le nom d&#39;un élève ou d&#39;un employé, puis cliquez sur <strong>Rechercher</strong>. Cliquez sur une personne pour ouvrir son dossier. Seules les personnes dont vous pouvez consulter au moins un type de document sont proposées.</li><li><strong>Documents déposés</strong> : la liste des documents, filtrée par défaut sur ceux <strong>À vérifier</strong> (déposés ou en vérification). Changez le filtre pour voir les documents validés, rejetés, ou tous ; choisissez un type pour ne voir que celui-là. Le champ <strong>Rechercher dans les documents</strong> retrouve un document par son intitulé, le nom de son fichier, ses notes ou le texte lu sur ses pages (voir <a href="/era-guide/guide/gestion-documentaire/numerisation.html">Numérisation</a>). Chaque ligne indique le type et la personne concernée : cliquez sur son nom pour ouvrir son dossier.</li></ul><p>Le bouton <strong>Documents de l&#39;établissement</strong> ouvre le dossier de l&#39;établissement, quand vous consultez au moins un type qui s&#39;y range.</p><h2 id="le-dossier-d-une-personne" tabindex="-1">Le dossier d&#39;une personne <a class="header-anchor" href="#le-dossier-d-une-personne" aria-label="Permalink to &quot;Le dossier d&#39;une personne&quot;">​</a></h2><p>Le dossier liste, type par type, tous les types de documents que vous pouvez consulter pour cette personne, avec les documents déposés sous chacun. Un type sans document affiche <strong>Aucun document</strong> : ce qui manque se voit aussi clairement que ce qui est là. Le haut de la page indique combien de types n&#39;ont encore aucun document.</p><p>Un administrateur ouvre aussi ce dossier depuis la fiche d&#39;un élève ou d&#39;un employé, avec le bouton <strong>Dossier documentaire</strong>.</p><h2 id="les-fichiers-des-autres-modules" tabindex="-1">Les fichiers des autres modules <a class="header-anchor" href="#les-fichiers-des-autres-modules" aria-label="Permalink to &quot;Les fichiers des autres modules {#les-fichiers-des-autres-modules}&quot;">​</a></h2><p>Le dossier montre aussi, sous leur type, les fichiers que les autres modules d&#39;ERA conservent déjà, sans les déplacer ni les copier :</p><table tabindex="0"><thead><tr><th>Fichier</th><th>Type de documents</th><th>Dossier</th></tr></thead><tbody><tr><td>Pièces jointes à une candidature approuvée</td><td>Dossier de candidature</td><td>Élève</td></tr><tr><td>Bulletins publiés</td><td>Bulletin</td><td>Élève</td></tr><tr><td>Reçus de paiement</td><td>Facture ou reçu</td><td>Élève</td></tr><tr><td>Justificatifs d&#39;absence envoyés</td><td>Justificatif d&#39;absence</td><td>Élève</td></tr><tr><td>Procès-verbaux de conseil de discipline</td><td>Procès-verbal de conseil de discipline</td><td>Élève</td></tr><tr><td>Relevés de notes publiés (supérieur)</td><td>Relevé de notes</td><td>Élève</td></tr><tr><td>Attestations de réussite (supérieur)</td><td>Attestation</td><td>Élève</td></tr><tr><td>Contrats de travail joints à la fiche employé</td><td>Contrat de travail</td><td>Employé</td></tr><tr><td>Justificatifs joints aux dépenses</td><td>Justificatif de dépense</td><td>Établissement</td></tr></tbody></table><p>Ces fichiers portent l&#39;étiquette du module qui les conserve (<strong>Bulletins</strong>, <strong>Caisse</strong>, <strong>Vie scolaire</strong>…) et le bouton <strong>Ouvrir</strong>. Ils ne passent pas par la vérification : ils se gèrent depuis leur module, comme avant. Les relevés de notes et attestations sont produits au moment où vous les ouvrez, à partir de ce que le jury a publié.</p><p>Qui les voit dépend de leur type dans le catalogue : par exemple, par défaut, le secrétariat voit les bulletins et les reçus, mais pas les procès-verbaux de conseil de discipline, réservés au gestionnaire et à la vie scolaire. Si l&#39;établissement supprime un de ces types, ses fichiers n&#39;apparaissent plus dans les dossiers.</p><h2 id="deposer-un-document" tabindex="-1">Déposer un document <a class="header-anchor" href="#deposer-un-document" aria-label="Permalink to &quot;Déposer un document&quot;">​</a></h2><p>Le bouton <strong>Déposer</strong> à côté d&#39;un type range le document sous ce type. Le bouton <strong>Ajouter un document</strong>, en haut du dossier, laisse choisir le type dans la fenêtre, ou en créer un : voir <a href="#un-type-qui-n-existe-pas-encore">Un type qui n&#39;existe pas encore</a>.</p><ol><li>Dans le dossier, cliquez sur <strong>Déposer</strong> à côté du type concerné.</li><li>Choisissez le <strong>Fichier</strong> : un PDF ou une image (JPG, PNG, WebP), de 10 Mo au plus. Pour un papier que vous avez sous la main, choisissez plutôt <strong>Photos des pages</strong> et photographiez-le au téléphone : voir <a href="/era-guide/guide/gestion-documentaire/numerisation.html">Numérisation</a>.</li><li>Renseignez si besoin un <strong>Intitulé</strong> (par exemple « Acte de naissance n° 1234 »), la <strong>Date du document</strong> (celle qu&#39;il porte) et des <strong>Notes</strong>.</li><li>Si vous pouvez valider ce type, la case <strong>Je l&#39;ai vérifié : le valider tout de suite</strong> est cochée : le document est validé dès le dépôt. C&#39;est le cas habituel au guichet, quand vous avez l&#39;original sous les yeux. Décochez-la pour le laisser à vérifier.</li><li>Cliquez sur <strong>Déposer</strong>.</li></ol><h3 id="un-type-qui-n-existe-pas-encore" tabindex="-1">Un type qui n&#39;existe pas encore <a class="header-anchor" href="#un-type-qui-n-existe-pas-encore" aria-label="Permalink to &quot;Un type qui n&#39;existe pas encore {#un-type-qui-n-existe-pas-encore}&quot;">​</a></h3><p>Le catalogue ne peut pas prévoir tous les papiers qu&#39;un établissement garde. Pour en ranger un d&#39;un genre nouveau :</p><ol><li>Cliquez sur <strong>Ajouter un document</strong> en haut du dossier.</li><li>Dans <strong>Type de document</strong>, choisissez <strong>Autre type…</strong>.</li><li>Tapez le <strong>Nom du nouveau type</strong> (par exemple « Carnet de vaccination »), et cochez <strong>Document confidentiel</strong> si besoin.</li><li>Joignez le fichier et complétez la fenêtre comme pour tout dépôt.</li></ol><p>Le nouveau type rejoint le catalogue, dans le dossier où vous êtes. Il est ouvert à votre profil et au gestionnaire documentaire, qui consultent et valident ses documents. Le gestionnaire peut ensuite l&#39;ajuster dans les <a href="/era-guide/guide/gestion-documentaire/types-de-documents.html">Types de documents</a>.</p><p>Si le nom tapé est celui d&#39;un type qui existe déjà (accents et majuscules mis à part), le document est rangé sous ce type, sans créer de doublon. Si ce type vous est fermé, ERA refuse le dépôt.</p><p>Un nouveau type se crée depuis un dossier que vous consultez déjà : un profil qui ne range aucun document dans les dossiers des employés ne peut pas en créer pour eux.</p><h2 id="verifier-un-document" tabindex="-1">Vérifier un document <a class="header-anchor" href="#verifier-un-document" aria-label="Permalink to &quot;Vérifier un document&quot;">​</a></h2><p>Un document déposé passe par ces statuts :</p><table tabindex="0"><thead><tr><th>Statut</th><th>Ce qu&#39;il signifie</th></tr></thead><tbody><tr><td><strong>Déposé</strong></td><td>Le document attend d&#39;être vérifié</td></tr><tr><td><strong>En vérification</strong></td><td>Quelqu&#39;un l&#39;a pris en main : les autres voient qu&#39;il est en cours</td></tr><tr><td><strong>Validé</strong></td><td>Le document a été vérifié et accepté</td></tr><tr><td><strong>Rejeté</strong></td><td>Le document a été refusé ; le motif est affiché, pour qu&#39;il soit refourni</td></tr></tbody></table><p>Si vous pouvez valider le type, chaque document en attente propose :</p><ul><li><strong>Ouvrir</strong> — affiche le fichier dans un nouvel onglet ;</li><li><strong>Prendre en vérification</strong> — le passe à <strong>En vérification</strong> à votre nom ;</li><li><strong>Valider</strong> — l&#39;accepte ;</li><li><strong>Rejeter</strong> — le refuse : indiquez le <strong>motif du rejet</strong>, obligatoire. Il reste affiché sous le document.</li></ul><p>Le <a href="/era-guide/guide/prise-en-main.html">tableau de bord</a> rappelle combien de documents attendent votre vérification, pour les seuls types que vous pouvez valider.</p><p>Une fois validé ou rejeté, un document ne change plus de statut. Pour remplacer un document rejeté, déposez-en un nouveau.</p><h2 id="supprimer-un-document" tabindex="-1">Supprimer un document <a class="header-anchor" href="#supprimer-un-document" aria-label="Permalink to &quot;Supprimer un document&quot;">​</a></h2><p>Un administrateur ou le gestionnaire documentaire peut supprimer tout document qu&#39;il consulte. Celui qui a déposé un document peut le retirer tant que personne ne l&#39;a pris en vérification. La suppression efface le fichier définitivement et est inscrite au journal d&#39;activité.</p><p>Un document archivé ne se supprime plus ainsi : il passe par une destruction approuvée, voir <a href="/era-guide/guide/gestion-documentaire/conservation.html">Conservation</a>.</p><h2 id="documents-confidentiels" tabindex="-1">Documents confidentiels <a class="header-anchor" href="#documents-confidentiels" aria-label="Permalink to &quot;Documents confidentiels&quot;">​</a></h2><p>Un type marqué <strong>Confidentiel</strong> (le dossier médical, le contrat de travail au départ) n&#39;est ouvert qu&#39;aux profils que son type désigne. Chaque fois que quelqu&#39;un ouvre un de ses documents, ERA l&#39;inscrit au <a href="/era-guide/guide/admin/demo-et-journal.html">journal d&#39;activité</a> avec l&#39;action <strong>Consulté</strong>, la personne et l&#39;adresse depuis laquelle elle l&#39;a ouvert.</p><p>Pour régler qui consulte et valide chaque type, voir <a href="/era-guide/guide/gestion-documentaire/types-de-documents.html">Types de documents</a>.</p>',38)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
